1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Single source of truth for an owner's {@code identityKey} — the one derived value that all
9	 * duplicate detection is now expressed through. The key is
10	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, so two owners are
11	 * duplicates only when their WHOLE keys match: two members of the same household (same
12	 * {@code householdId}) with different telephones have different keys and are both allowed.
13	 *
14	 * <p>The three parts are normalized the same way they are stored: the telephone to its E.164
15	 * form (see {@link OwnerTelephones}, so a stored value that predates the pipeline still
16	 * compares correctly), the email trimmed and lower-cased (empty when absent), and the
17	 * {@code householdId} as stored (empty when absent). Used by {@link RejectDuplicateIdentity}
18	 * to find collisions and by the owner mapper to return the key.
19	 */
20	public final class OwnerIdentity {
21	
22	    private OwnerIdentity() {
23	    }
24	
25	    /** The owner's duplicate-detection identity key. */
26	    public static String identityKey(Owner owner) {
27	        String telephone = OwnerTelephones.toE164(owner.getTelephone());
28	        if (telephone == null) {
29	            telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
30	        }
31	        String email = owner.getEmail();
32	        email = (email == null || email.isBlank()) ? "" : email.trim().toLowerCase(Locale.ROOT);
33	        String household = owner.getHouseholdId();
34	        household = household == null ? "" : household;
35	        return telephone + "|" + email + "|" + household;
36	    }
37	}
