10	import org.springframework.validation.annotation.Validated;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	@Validated
14	public class BuildOwner {
15	
16	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
17	            Out<Boolean> sharesHousehold) {
18	        Owner owner = ownerMapper.toOwner(request);
19	        // Establish the raw registration date, defaulting an absent one to the server
20	        // date. NormalizeOwnerRegistrationDate later rolls a weekend forward to a
21	        // business day; derived values (membership number, daily limit) read it back
22	        // off the owner, so they see the adjusted date regardless.
23	        if (owner.getRegistrationDate() == null) {
24	            owner.setRegistrationDate(LocalDate.now());
25	        }
26	        built.set(owner);
27	        // sharesHousehold is a create-time flag, not an Owner field; republish it for
28	        // AssignHousehold. Absent in the body means false.
29	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
30	    }
31	}
