1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * The registration date must fall on a business day. Whatever the owner's effective
11	 * registration date — supplied in the request or defaulted by {@link BuildOwner} — a
12	 * Saturday rolls forward two days and a Sunday one day to the following Monday, stored
13	 * back on the owner. Weekdays are left unchanged. Everything derived from the
14	 * registration date (the membership number's year segment, the daily create-limit)
15	 * reads it back off the owner, so it sees the adjusted date.
16	 */
17	public class NormalizeOwnerRegistrationDate {
18	
19	    public void service(@Val Owner owner) {
20	        LocalDate registrationDate = owner.getRegistrationDate();
21	        DayOfWeek day = registrationDate.getDayOfWeek();
22	        if (day == DayOfWeek.SATURDAY) {
23	            owner.setRegistrationDate(registrationDate.plusDays(2));
24	        } else if (day == DayOfWeek.SUNDAY) {
25	            owner.setRegistrationDate(registrationDate.plusDays(1));
26	        }
27	    }
28	}
