2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
25	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "bulkSignupWarning",
29	        expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
30	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
31	    @Mapping(target = "identityKey",
32	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner))")
33	    OwnerDto toOwnerDto(Owner owner);
34	
35	    /**
36	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email
37	     * address is present (non-null and not blank), otherwise {@code PHONE}.
38	     */
39	    default String contactPreference(Owner owner) {
40	        String email = owner.getEmail();
41	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
42	    }
43	
44	    /**
45	     * Fixed city-to-region table used as the fallback when the postcode does not
46	     * resolve a region.
47	     */
48	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
49	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
50	
51	    /**
52	     * Region-to-inclusive 4-digit postcode range {low, high}, used to resolve the
53	     * locality by postcode first.
54	     */
55	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
56	        "NSW", new int[] {2000, 2099},
57	        "VIC", new int[] {3000, 3099},
58	        "QLD", new int[] {4000, 4099});
59	
60	    /**
61	     * Derives the owner's locality (region), preferring the postcode: a 4-digit
62	     * postcode falling within a known region's inclusive range yields that region.
63	     * When the postcode is absent or in no known range, falls back to the
64	     * {@link #CITY_REGION} table, returning {@code UNKNOWN} when the city is not
65	     * listed.
66	     *
67	     * <p>The postcode lookup is inlined here (rather than a helper method) because
68	     * MapStruct would otherwise treat a {@code String}-to-{@code String} default
69	     * method as an implicit field mapping and apply it to every string property.
70	     */
71	    default String locality(Owner owner) {
72	        String postcode = owner.getPostcode();
73	        if (postcode != null && postcode.matches("[0-9]{4}")) {
74	            int value = Integer.parseInt(postcode);
75	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
76	                int[] range = entry.getValue();
77	                if (value >= range[0] && value <= range[1]) {
78	                    return entry.getKey();
79	                }
80	            }
81	        }
82	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
83	    }
84	
85	    /**
86	     * Derives the owner's membership number, formatted {@code <customerCode>-M<YY>}
87	     * where {@code YY} is the last two digits of the registration-date year
88	     * (e.g. {@code LON-SMI-0007-M26}). Null when either source field is absent.
89	     */
90	    default String membershipNumber(Owner owner) {
91	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
92	            return null;
93	        }
94	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
95	    }
96	
97	    /**
98	     * Computes a single Luhn check digit (0-9) over the digits contained in the
99	     * owner's {@code customerCode}. Null when the customer code is absent.
100	     */
101	    default Integer checkDigit(Owner owner) {
102	        String customerCode = owner.getCustomerCode();
103	        if (customerCode == null) {
104	            return null;
105	        }
106	        int sum = 0;
107	        boolean dbl = true;
108	        for (int i = customerCode.length() - 1; i >= 0; i--) {
109	            char c = customerCode.charAt(i);
110	            if (c < '0' || c > '9') {
111	                continue;
112	            }
113	            int d = c - '0';
114	            if (dbl) {
115	                d *= 2;
116	                if (d > 9) {
117	                    d -= 9;
118	                }
119	            }
120	            sum += d;
121	            dbl = !dbl;
122	        }
123	        return (10 - (sum % 10)) % 10;
124	    }
125	
126	    Owner toOwner(OwnerDto ownerDto);
127	
128	    @Mapping(target = "id", ignore = true)
129	    @Mapping(target = "pets", ignore = true)
130	    Owner toOwner(OwnerFieldsDto ownerDto);
131	
132	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
133	
134	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
135	
136	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
137	        OwnerPageDto ownerPageDto = new OwnerPageDto();
138	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
139	        ownerPageDto.setPage(ownerPage.getNumber());
140	        ownerPageDto.setSize(ownerPage.getSize());
141	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
142	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
143	        return ownerPageDto;
144	    }
145	}
