1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Single source of truth for the owner "E.164 telephone" rule. Both
8	 * {@link NormalizeOwnerTelephone} (which stores the E.164 value) and
9	 * {@link OwnerIdentity} (which uses it as the telephone part of the identity key) go through
10	 * here, so the two can never drift apart.
11	 *
12	 * <p>The rule: strip spaces, dashes and brackets; keep a leading {@code '+'} and country
13	 * code when present, otherwise assume country code {@code '+61'} and drop a single leading
14	 * {@code '0'} from the national digits; require 8 to 15 digits after the {@code '+'}. So
15	 * {@code "0412 345 678"} becomes {@code "+61412345678"}.
16	 *
17	 * <p>For a recognised country code the national-number length is also fixed: {@code '+61'}
18	 * requires exactly 9 national digits and {@code '+1'} exactly 10. A number whose country
19	 * code is known but whose national length is wrong is rejected (returns {@code null}).
20	 */
21	final class OwnerTelephones {
22	
23	    /**
24	     * Recognised country codes mapped to the exact number of national digits they require.
25	     * Ordered longest-prefix first so a leading {@code "61"} matches country {@code "61"}
26	     * before the shorter {@code "1"}.
27	     */
28	    private static final Map<String, Integer> NATIONAL_DIGITS = new LinkedHashMap<>();
29	
30	    static {
31	        NATIONAL_DIGITS.put("61", 9);
32	        NATIONAL_DIGITS.put("1", 10);
33	    }
34	
35	    private OwnerTelephones() {
36	    }
37	
38	    /**
39	     * Converts {@code telephone} to its E.164 form, or returns {@code null} when it cannot
40	     * form a valid E.164 number (null input, non-digit content, fewer than 8 / more than
41	     * 15 digits after the {@code '+'}, or a recognised country code with the wrong
42	     * national-number length).
43	     */
44	    static String toE164(String telephone) {
45	        if (telephone == null) {
46	            return null;
47	        }
48	        // Strip spaces, dashes and brackets; any other non-digit is left in place so it
49	        // fails the digits check below.
50	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
51	        String digits;
52	        if (cleaned.startsWith("+")) {
53	            // Explicit country code: keep it, drop the leading '+'.
54	            digits = cleaned.substring(1);
55	        } else {
56	            // No country code: assume '+61' and drop a single leading '0' from the national
57	            // digits.
58	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
59	            digits = "61" + national;
60	        }
61	        if (!digits.matches("\\d{8,15}")) {
62	            return null;
63	        }
64	        // For a recognised country code, the national-number length is fixed.
65	        for (Map.Entry<String, Integer> country : NATIONAL_DIGITS.entrySet()) {
66	            String code = country.getKey();
67	            if (digits.startsWith(code)) {
68	                int nationalLength = digits.length() - code.length();
69	                return nationalLength == country.getValue() ? "+" + digits : null;
70	            }
71	        }
72	        return "+" + digits;
73	    }
74	}
