1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the owner's telephone to E.164 form (see {@link OwnerTelephones}): strip
9	 * spaces, dashes and brackets; keep a leading '+' and country code when present, otherwise
10	 * assume country code '+61' and drop a single leading '0' from the national digits; require
11	 * 8 to 15 digits after the '+', and the exact national-number length for a recognised
12	 * country code ('+61' => 9, '+1' => 10). The E.164 value is stored back on the owner (so it
13	 * is persisted and returned); anything that cannot form a valid E.164 number escalates as a
14	 * 400 via {@link InvalidTelephoneException}.
15	 */
16	public class NormalizeOwnerTelephone {
17	
18	    public void service(@Val Owner owner) throws InvalidTelephoneException {
19	        String e164 = OwnerTelephones.toE164(owner.getTelephone());
20	        if (e164 == null) {
21	            throw new InvalidTelephoneException(
22	                    "Telephone cannot be formatted as a valid E.164 number "
23	                            + "(8 to 15 digits after the country code, and the national-number "
24	                            + "length must match the country code: '+61' needs 9 digits, "
25	                            + "'+1' needs 10)");
26	        }
27	        owner.setTelephone(e164);
28	    }
29	}
